<span class="line">        std<span class="token double-colon punctuation">::</span>future<span class="token operator">&lt;</span>ReturnType<span class="token operator">&gt;</span> result <span class="token operator">=</span> task<span class="token operator">-&gt;</span><span class="token function">get_future</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
